{
  "governing": {
    "citation_id": "CGST/r43@v4",
    "in_force": "2023-10-01 to date",
    "covers_ref_date": true
  },
  "abstain": false,
  "ref_date_used": "2023-10-01",
  "claims": [
    {
      "kind": "conclusion",
      "text": "Rule 43 provides the manner of determination of input tax credit in respect of capital goods and reversal thereof in certain cases.",
      "citation_ids": [
        "CGST/r43@v4"
      ]
    },
    {
      "kind": "condition",
      "text": "The input tax credit in respect of capital goods, which attract the provisions of sub-sections (1) and (2) of section 17, being partly used for the purposes of business and partly for other purposes, or partly used for effecting taxable supplies including zero rated supplies and partly for effecting exempt supplies, shall be attributed to the purposes of business or for effecting taxable supplies subject to the provisions of sub-section (3) of section 16.",
      "citation_ids": [
        "CGST/r43@v4"
      ]
    },
    {
      "kind": "conclusion",
      "text": "The amount of input tax in respect of capital goods used or intended to be used exclusively for non-business purposes or used or intended to be used exclusively for effecting exempt supplies shall be indicated in FORM GSTR-3B and shall not be credited to his electronic credit ledger.",
      "citation_ids": [
        "CGST/r43@v4"
      ]
    },
    {
      "kind": "conclusion",
      "text": "The amount of input tax in respect of capital goods used or intended to be used exclusively for effecting supplies other than exempted supplies but including zero-rated supplies shall be indicated in FORM GSTR-3B and shall be credited to the electronic credit ledger.",
      "citation_ids": [
        "CGST/r43@v4"
      ]
    }
  ],
  "assumptions": []
}

{
  "governing": {
    "citation_id": "CGST/r45@v1",
    "in_force": "2021-05-18 to 2021-09-30",
    "covers_ref_date": true
  },
  "abstain": false,
  "ref_date_used": "2021-09-30",
  "claims": [
    {
      "kind": "conclusion",
      "text": "Rule 45 provides conditions and restrictions in respect of inputs and capital goods sent to the job worker.",
      "citation_ids": [
        "CGST/r45@v1"
      ]
    },
    {
      "kind": "condition",
      "text": "The inputs, semi-finished goods or capital goods shall be sent to the job worker under the cover of a challan issued by the principal, including where such goods are sent directly to a job-worker, and where the goods are sent from one job worker to another job worker, the challan may be issued either by the principal or the job worker sending the goods to another job worker.",
      "citation_ids": [
        "CGST/r45@v1"
      ]
    },
    {
      "kind": "exception",
      "text": "The challan issued by the principal may be endorsed by the job worker, indicating therein the quantity and description of goods where the goods are sent by one job worker to another or are returned to the principal.",
      "citation_ids": [
        "CGST/r45@v1"
      ]
    },
    {
      "kind": "exception",
      "text": "The challan endorsed by the job worker may be further endorsed by another job worker, indicating therein the quantity and description of goods where the goods are sent by one job worker to another or are returned to the principal.",
      "citation_ids": [
        "CGST/r45@v1"
      ]
    },
    {
      "kind": "condition",
      "text": "The challan issued by the principal to the job worker shall contain the details specified in rule 55.",
      "citation_ids": [
        "CGST/r45@v1"
      ]
    },
    {
      "kind": "condition",
      "text": "The details of challans in respect of goods dispatched to a job worker or received from a job worker during a quarter shall be included in FORM GST ITC-04 furnished for that period on or before the twenty-fifth day of the month succeeding the said quarter or within such further period as may be extended by the Commissioner by a notification in this behalf.",
      "citation_ids": [
        "CGST/r45@v1"
      ]
    },
    {
      "kind": "exception",
      "text": "Any extension of the time limit notified by the Commissioner of State tax or the Commissioner of Union territory tax shall be deemed to be notified by the Commissioner.",
      "citation_ids": [
        "CGST/r45@v1"
      ]
    },
    {
      "kind": "condition",
      "text": "Where the inputs or capital goods are not returned to the principal within the time stipulated in section 143, it shall be deemed that such inputs or capital goods had been supplied by the principal to the job worker on the day when the said inputs or capital goods were sent out and the said supply shall be declared in FORM GSTR-1 and the principal shall be liable to pay the tax along with applicable interest.",
      "citation_ids": [
        "CGST/r45@v1"
      ]
    }
  ],
  "assumptions": []
}

