{
  "governing": {
    "citation_id": "CGST/r48@v1",
    "in_force": "2021-05-18 to 2024-07-09",
    "covers_ref_date": true
  },
  "abstain": false,
  "ref_date_used": "2024-07-09",
  "claims": [
    {
      "kind": "conclusion",
      "text": "Rule 48 of the Central Goods and Services Tax Rules, 2017 provides the manner of issuing invoice.",
      "citation_ids": [
        "CGST/r48@v1"
      ]
    },
    {
      "kind": "conclusion",
      "text": "The invoice shall be prepared in triplicate, in the case of supply of goods, with the original copy being marked as ORIGINAL FOR RECIPIENT, the duplicate copy being marked as DUPLICATE FOR TRANSPORTER, and the triplicate copy being marked as TRIPLICATE FOR SUPPLIER.",
      "citation_ids": [
        "CGST/r48@v1"
      ]
    },
    {
      "kind": "conclusion",
      "text": "The invoice shall be prepared in duplicate, in the case of the supply of services, with the original copy being marked as ORIGINAL FOR RECIPIENT and the duplicate copy being marked as DUPLICATE FOR SUPPLIER.",
      "citation_ids": [
        "CGST/r48@v1"
      ]
    },
    {
      "kind": "conclusion",
      "text": "The serial number of invoices issued during a tax period shall be furnished electronically through the common portal in FORM GSTR-1.",
      "citation_ids": [
        "CGST/r48@v1"
      ]
    },
    {
      "kind": "conclusion",
      "text": "The invoice shall be prepared by such class of registered persons as may be notified by the Government, on the recommendations of the Council, by including such particulars contained in FORM GST INV-01 after obtaining an Invoice Reference Number by uploading information contained therein on the Common Goods and Services Tax Electronic Portal in such manner and subject to such conditions and restrictions as may be specified in the notification.",
      "citation_ids": [
        "CGST/r48@v1"
      ]
    },
    {
      "kind": "exception",
      "text": "The Commissioner may, on the recommendations of the Council, by notification, exempt a person or a class of registered persons from issuance of invoice under sub-rule (4) for a specified period, subject to such conditions and restrictions as may be specified in the said notification.",
      "citation_ids": [
        "CGST/r48@v1"
      ]
    },
    {
      "kind": "conclusion",
      "text": "Every invoice issued by a person to whom sub-rule (4) applies in any manner other than the manner specified in the said sub-rule shall not be treated as an invoice.",
      "citation_ids": [
        "CGST/r48@v1"
      ]
    },
    {
      "kind": "exception",
      "text": "The provisions of sub-rules (1) and (2) shall not apply to an invoice prepared in the manner specified in sub-rule (4).",
      "citation_ids": [
        "CGST/r48@v1"
      ]
    }
  ],
  "assumptions": []
}

