{
  "governing": {
    "citation_id": "CGST/r89@v5",
    "in_force": "2022-10-01 to 2022-12-25",
    "covers_ref_date": true
  },
  "abstain": false,
  "ref_date_used": "2022-12-25",
  "claims": [
    {
      "kind": "conclusion",
      "text": "Any person, except the persons covered under notification issued under section 55, claiming refund of any balance in the electronic cash ledger in accordance with the provisions of sub-section (6) of section 49 or any tax, interest, penalty, fees or any other amount paid by him, other than refund of integrated tax paid on goods exported out of India, may file, subject to the provisions of rule 10B, an application electronically in FORM GST RFD -01 through the common portal, either directly or through a Facilitation Centre notified by the Commissioner.",
      "citation_ids": [
        "CGST/r89@v5"
      ]
    },
    {
      "kind": "exception",
      "text": "Provided that in respect of supplies to a Special Economic Zone unit or a Special Economic Zone developer, the application for refund shall be filed by the – (a) supplier of goods after such goods have been admitted in full in the Special Economic Zone for authorised operations, as endorsed by the specified officer of the Zone; (b) supplier of services along with such evidence regarding receipt of services for authorised operations as endorsed by the specified officer of the Zone.",
      "citation_ids": [
        "CGST/r89@v5"
      ]
    },
    {
      "kind": "exception",
      "text": "Provided further that in respect of supplies regarded as deemed exports, the application may be filed by, - (a) the recipient of deemed export supplies; or (b) the supplier of deemed export supplies in cases where the recipient does not avail of input tax credit on such supplies and furnishes an undertaking to the effect that the supplier may claim the refund.",
      "citation_ids": [
        "CGST/r89@v5"
      ]
    },
    {
      "kind": "exception",
      "text": "Provided also that refund of any amount, after adjusting the tax payable by the applicant out of the advance tax deposited by him under section 27 at the time of registration, shall be claimed in the last return required to be furnished by him.",
      "citation_ids": [
        "CGST/r89@v5"
      ]
    },
    {
      "kind": "conclusion",
      "text": "Any person, claiming refund under section 77 of the Act of any tax paid by him, in respect of a transaction considered by him to be an intra-State supply, which is subsequently held to be an inter-State supply, may, before the expiry of a period of two years from the date of payment of the tax on the inter-State supply, file an application electronically in FORM GST RFD-01 through the common portal, either directly or through a Facilitation Centre notified by the Commissioner.",
      "citation_ids": [
        "CGST/r89@v5"
      ]
    },
    {
      "kind": "condition",
      "text": "The application under sub-rule (1) shall be accompanied by any of the documentary evidences in Annexure 1 in FORM GST RFD -01, as applicable, to establish that a refund is due to the applicant.",
      "citation_ids": [
        "CGST/r89@v5"
      ]
    },
    {
      "kind": "condition",
      "text": "Where the application relates to refund of input tax credit, the electronic credit ledger shall be debited by the applicant by an amount equal to the refund so claimed.",
      "citation_ids": [
        "CGST/r89@v5"
      ]
    }
  ],
  "assumptions": []
}

