{
  "governing": {
    "citation_id": "CGST/r91@v1",
    "in_force": "2021-05-18 to 2025-09-30",
    "covers_ref_date": true
  },
  "abstain": false,
  "ref_date_used": "2025-09-30",
  "claims": [
    {
      "kind": "conclusion",
      "text": "The provisional refund in accordance with the provisions of sub-section (6) of section 54 shall be granted subject to the condition that the person claiming refund has, during any period of five years immediately preceding the tax period to which the claim for refund relates, not been prosecuted for any offence under the Act or under an existing law where the amount of tax evaded exceeds two hundred and fifty lakh rupees.",
      "citation_ids": [
        "CGST/r91@v1"
      ]
    },
    {
      "kind": "conclusion",
      "text": "The proper officer, after scrutiny of the claim and the evidence submitted in support thereof and on being prima facie satisfied that the amount claimed as refund under sub-rule (1) is due to the applicant in accordance with the provisions of sub-section (6) of section 54, shall make an order in FORM GST RFD -04, sanctioning the amount of refund due to the said applicant on a provisional basis within a period not exceeding seven days from the date of the acknowledgement under sub-rule (1) or sub-rule (2) of rule 90.",
      "citation_ids": [
        "CGST/r91@v1"
      ]
    },
    {
      "kind": "exception",
      "text": "Provided that the order issued in FORM GST RFD-04 shall not be required to be revalidated by the proper officer.",
      "citation_ids": [
        "CGST/r91@v1"
      ]
    },
    {
      "kind": "conclusion",
      "text": "The proper officer shall issue a payment order in FORM GST RFD -05 for the amount sanctioned under sub-rule (2) and the same shall be electronically credited to any of the bank accounts of the applicant mentioned in his registration particulars and as specified in the application for refund on the basis of a consolidated payment advice.",
      "citation_ids": [
        "CGST/r91@v1"
      ]
    },
    {
      "kind": "exception",
      "text": "Provided that the payment order in FORM GST RFD -05 shall be required to be revalidated where the refund has not been disbursed within the same financial year in which the said payment order was issued.",
      "citation_ids": [
        "CGST/r91@v1"
      ]
    },
    {
      "kind": "conclusion",
      "text": "The Central Government shall disburse the refund based on the consolidated payment advice issued under sub-rule (3).",
      "citation_ids": [
        "CGST/r91@v1"
      ]
    }
  ],
  "assumptions": []
}

